            ...(low !== undefined ? { low } : {}),
            ...(last !== undefined ? { last } : {}),
            ...(change !== undefined ? { change } : {}),
            ...(percentage !== undefined ? { percentage } : {}),
            baseVolume: Structs.toHumanNum(stats.baseVolume24h, d.amount),
            quoteVolume: Structs.toHumanNum(stats.volume24h, d.price),
