                    fundingRate: Number(fundingRate8h(perp.fundingRate, perp.fundingWindowSec)) / 1e18,
                    fundingTimestamp: Number(perp.nextFundingAt) * 1000,
                    openInterest: Structs.toHumanNum(perp.openInterest, d.amount),
